package com.opensocket.aievent.core.issuetracking.application.recovery;
import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.opensocket.aievent.core.issuetracking.recovery.*;
@Service public class ProjectionReconciliationService {private final ProjectionRecoveryRepository repo;private final ProjectionRecoveryEventLedger ledger;public ProjectionReconciliationService(ProjectionRecoveryRepository repo,ProjectionRecoveryEventLedger ledger){this.repo=repo;this.ledger=ledger;}
 @Transactional public ProjectionReconciliationRun request(String tenant,String connection,String mapping,String scopeType,String scopeId,boolean dryRun,String actor,String correlation){OffsetDateTime now=now();var run=new ProjectionReconciliationRun(req(tenant),"rr-"+UUID.randomUUID(),req(connection),blank(mapping),req(scopeType),blank(scopeId),ReconciliationRunStatus.REQUESTED,dryRun,0,0,0,0,1,now,now,req(actor),correlation);repo.saveRun(run);ledger.append(tenant,"RECONCILIATION_RUN",run.runId(),ProjectionRecoveryEventType.RECONCILIATION_STARTED,actor,dryRun?"DRY_RUN":"REPAIR_ALLOWED","{}",correlation);return run;}
 @Transactional public ProjectionRecoveryCase recordDrift(String tenant,String runId,long expectedVersion,ProjectionRecoveryCaseType type,String laneId,String workId,String projectionId,String externalIssueId,String expectedHash,String observedHash,String actor,String reason,String correlation){var run=get(tenant,runId);if(run.version()!=expectedVersion)throw new IllegalStateException("RECONCILIATION_RUN_VERSION_CONFLICT");if(type==null||type==ProjectionRecoveryCaseType.RESPONSE_LOST||type==ProjectionRecoveryCaseType.PROVIDER_INDEX_DELAY)throw new IllegalArgumentException("A reconciliation drift case type is required.");OffsetDateTime now=now();var existing=workId==null||workId.isBlank()?Optional.<ProjectionRecoveryCase>empty():repo.findOpenCase(tenant,workId,type);if(existing.isPresent())return existing.get();var c=new ProjectionRecoveryCase(req(tenant),"prc-"+UUID.randomUUID(),type,ProjectionRecoveryCaseStatus.OPEN,blank(laneId),blank(workId),blank(projectionId),run.connectionId(),run.projectMappingId(),"",blank(externalIssueId),blank(expectedHash),blank(observedHash),type.name(),requiredReason(reason),1,null,1,now,now,correlation);repo.saveCase(c);var next=new ProjectionReconciliationRun(run.tenantId(),run.runId(),run.connectionId(),run.projectMappingId(),run.scopeType(),run.scopeId(),ReconciliationRunStatus.SCANNING,run.dryRun(),run.scannedCount()+1,run.driftCount()+1,run.repairedCount(),run.failedCount(),run.version()+1,run.createdAt(),now,run.requestedBy(),correlation);if(!repo.saveRunExpectedVersion(next,run.version()))throw new IllegalStateException("RECONCILIATION_RUN_VERSION_CONFLICT");ledger.append(tenant,"RECONCILIATION_RUN",runId,ProjectionRecoveryEventType.DRIFT_DETECTED,actor,type.name(),json("caseId",c.caseId()),correlation);return c;}
 @Transactional public ProjectionReconciliationRun complete(String tenant,String runId,long expectedVersion,int scanned,int repaired,int failed,String actor,String reason,String correlation){var run=get(tenant,runId);if(run.version()!=expectedVersion)throw new IllegalStateException("RECONCILIATION_RUN_VERSION_CONFLICT");OffsetDateTime now=now();ReconciliationRunStatus status=failed>0?ReconciliationRunStatus.PARTIAL:ReconciliationRunStatus.COMPLETED;var next=new ProjectionReconciliationRun(run.tenantId(),run.runId(),run.connectionId(),run.projectMappingId(),run.scopeType(),run.scopeId(),status,run.dryRun(),Math.max(run.scannedCount(),scanned),run.driftCount(),Math.max(run.repairedCount(),repaired),Math.max(run.failedCount(),failed),run.version()+1,run.createdAt(),now,run.requestedBy(),correlation);if(!repo.saveRunExpectedVersion(next,run.version()))throw new IllegalStateException("RECONCILIATION_RUN_VERSION_CONFLICT");ledger.append(tenant,"RECONCILIATION_RUN",runId,ProjectionRecoveryEventType.REPAIR_VERIFIED,actor,requiredReason(reason),json("status",status.name()),correlation);return next;}
 public List<ProjectionReconciliationRun> list(String tenant,ReconciliationRunStatus status,int limit){return repo.listRuns(req(tenant),status,Math.max(1,Math.min(limit,1000)));}public ProjectionReconciliationRun get(String tenant,String runId){return repo.findRun(req(tenant),req(runId)).orElseThrow(()->new IllegalArgumentException("Reconciliation run not found."));}private String req(String v){if(v==null||v.isBlank())throw new IllegalArgumentException("Required value missing.");return v.trim();}private String requiredReason(String v){String s=req(v);if(s.length()<8)throw new IllegalArgumentException("Governance reason must contain at least 8 characters.");return s;}private String blank(String v){return v==null?"":v.trim();}private OffsetDateTime now(){return OffsetDateTime.now(ZoneOffset.UTC);}private String json(String k,String v){String s=v==null?"":v.replace("\\","\\\\").replace("\"","'");return "{\""+k+"\":\""+s+"\"}";}}
